fn validate_ignore_signals(opts: &Options<'_>) -> UResult<()> {
    for &(signal, ignore_errors) in &opts.ignore_signals {
        match set_ignore_signal(signal) {
            Ok(old_action) => {
                let _ = unsafe { sigaction(signal, &old_action) };
            }
            Err(error) => {
                if !ignore_errors {
                    return Err(USimpleError::new(
